<!DOCTYPE html>
<html lang="hu">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Kutatóágens</title>
<style>
body {
font-family: 'Segoe UI', sans-serif;
margin: 0;
padding: 0;
background-color: #0e0e10;
color: #ffffff;
}
header {
display: flex;
align-items: center;
justify-content: space-between;
padding: 12px 20px;
background-color: #111;
border-bottom: 1px solid #2a2a2a;
}
header h1 {
font-size: 18px;
margin: 0;
color: #0af;
}
button, select, input {
background-color: #1d1f22;
color: #fff;
border: 1px solid #333;
border-radius: 6px;
padding: 8px 12px;
}
button:hover {
background-color: #292b2f;
cursor: pointer;
}
.container {
padding: 20px;
max-width: 800px;
margin: auto;
}
.section {
margin-bottom: 30px;
padding: 20px;
background-color: #141416;
border-radius: 8px;
box-shadow: 0 0 10px rgba(0,0,0,0.4);
}
.section h2 {
margin-top: 0;
color: #0af;
}
label {
display: block;
margin: 10px 0 6px;
}
input[type="text"], input[type="number"], select {
width: 100%;
}
.action-buttons {
margin-top: 20px;
display: flex;
justify-content: flex-end;
gap: 10px;
}
.menu {
display: flex;
gap: 10px;
}
.menu button {
background-color: #0af;
border: none;
color: #fff;
}
.side-menu, .bottom-history, .live-widget, .report-modal {
display: none;
position: fixed;
background-color: #111;
color: #fff;
z-index: 999;
}
.side-menu {
top: 0;
left: 0;
width: 260px;
height: 100%;
padding: 20px;
border-right: 1px solid #0af;
overflow-y: auto;
}
.bottom-history {
bottom: 0;
left: 0;
width: 100%;
max-height: 45%;
overflow-y: auto;
border-top: 1px solid #0af;
padding: 20px;
}
.live-widget {
bottom: 100px;
left: 50%;
transform: translateX(-50%);
width: 600px;
height: 300px;
overflow-y: auto;
border: 2px solid #0af;
border-radius: 8px;
box-shadow: 0 0 30px rgba(0,153,255,0.3);
animation: pulse 2s infinite alternate;
}
@keyframes pulse {
0% {border-color: #008cff;}
100% {border-color: #00aeff;}
}
.report-modal {
top: 0;
left: 0;
width: 100%;
height: 100%;
background-color: rgba(0,0,0,0.95);
padding: 40px;
overflow-y: auto;
}
.report-card {
background-color: #151515;
padding: 20px;
border-radius: 8px;
margin-top: 20px;
}
.report-card h3 {
margin-top: 0;
}
.close-btn {
position: absolute;
top: 20px;
right: 30px;
font-size: 20px;
cursor: pointer;
color: #ccc;
}
.report-modal-content {
background-color: #1a1a1d;
padding: 30px;
border-radius: 10px;
}
footer {
text-align: center;
padding: 20px;
border-top: 1px solid #2a2a2a;
color: #777;
}
</style>
</head>
<body>
<header>
<button id="hamburger">☰</button>
<h1>AI Kutatóágens</h1>
<div class="menu">
<button id="menu-btn">⋯</button>
</div>
</header>
<div id="side-menu" class="side-menu">
<h3>Előzmények</h3>
<div id="history-list"></div>
<hr>
<button id="new-chat">Új beszélgetés</button>
</div>
<div class="container">
<div class="section">
<h2>Professzionális AI-alapú kutatás<br>valós időben</h2>
<p>Adj meg egy kérdést, és az AI autonóm módon végez átfogó kutatást számodra valós források alapján.</p>
<label for="query">🔍 Kutatási kérdés</label>
<input type="text" id="query" placeholder="Írd ide a kutatási kérdést...">
<label for="mode">🎯 Kutatási mód</label>
<select id="mode">
<option value="quick">Gyors kutatás</option>
<option value="deep">Mély kutatás</option>
<option value="autonomous">Autonóm mód</option>
</select>
<label for="time">⏱️ Időlimit (perc)</label>
<input type="number" id="time" min="1" value="5">
<label for="sources">📚 Maximum források száma</label>
<input type="number" id="sources" min="1" value="10">
<div class="action-buttons">
<button id="start">Kutatás indítása</button>
</div>
</div>
<div class="section">
<h2>Kutatások</h2>
<div id="research-list"></div>
</div>
<div class="section">
<h2>Jelentések</h2>
<div id="report-list"></div>
</div>
<div class="section">
<h2>⚙️ Beállítások</h2>
<label>🎯 Alapértelmezett kutatási mód</label>
<select id="default-mode">
<option value="quick">Gyors</option>
<option value="deep">Mély</option>
<option value="autonomous">Autonóm</option>
</select>
<label>⏱️ Alapértelmezett időlimit (perc)</label>
<input type="number" id="default-time" min="1" value="5">
<label>📚 Alapértelmezett max források</label>
<input type="number" id="default-sources" min="1" value="10">
<label>🎨 Téma</label>
<div>
<button id="dark-theme">Sötét téma</button>
<button id="light-theme">☀️ Világos téma</button>
</div>
<div class="action-buttons">
<button id="save-settings">Beállítások mentése</button>
<button id="clear-cache">🗑️ Cache törlése</button>
</div>
</div>
</div>
<div id="bottom-history" class="bottom-history">
<input type="text" placeholder="Keresés az előzményekben...">
<ul id="history-items"></ul>
</div>
<div id="live-widget" class="live-widget"></div>
<div id="report-modal" class="report-modal">
<div class="close-btn" id="close-report">✖</div>
<div class="report-modal-content" id="report-content"></div>
</div>
<footer>
<p>© 2025 AI Kutatóágens</p>
</footer>
<script>
const hamburger=document.getElementById("hamburger");
const sideMenu=document.getElementById("side-menu");
const menuBtn=document.getElementById("menu-btn");
const bottomHistory=document.getElementById("bottom-history");
const startBtn=document.getElementById("start");
const liveWidget=document.getElementById("live-widget");
const reportModal=document.getElementById("report-modal");
const reportContent=document.getElementById("report-content");
const closeReport=document.getElementById("close-report");
hamburger.addEventListener("click",()=>{sideMenu.style.display=sideMenu.style.display==="block"?"none":"block";});
menuBtn.addEventListener("click",()=>{bottomHistory.style.display=bottomHistory.style.display==="block"?"none":"block";});
startBtn.addEventListener("click",()=>{
const query=document.getElementById("query").value;
if(!query.trim())return;
liveWidget.innerHTML="";
liveWidget.style.display="block";
let steps=[
"[Gondolat] Értelmezem a kérést. Fókuszpontok: anyagfáradás, magas hőmérséklet.",
"[Terv] 1. Alapvető definíciók keresése. 2. Aktuális tanulmányok gyűjtése.",
"[🌐 Keresés] \"tokamak plasma-facing material fatigue 2024\"",
"[📄 Elemzés] Forrás feldolgozása: 'nature.com/fusion...'",
"[Gondolat] Érdekes adat a wolfram eróziójáról. Ezt feljegyzem.",
"[🌐 Keresés] \"stellarator magnetic coil limitations 2025\"",
"[📄 Elemzés] Forrás feldolgozása: 'sciencedirect.com/...'",
"[Szintézis] Az adatok összevetése, a jelentés vázlatának elkészítése...",
"[✔️ Befejezve] A jelentés összeállítása..."
];
let i=0;
let interval=setInterval(()=>{
if(i<steps.length){
const p=document.createElement("p");
p.textContent=steps[i];
liveWidget.appendChild(p);
liveWidget.scrollTop=liveWidget.scrollHeight;
i++;
}else{
clearInterval(interval);
setTimeout(()=>{
liveWidget.style.animation="none";
let card=document.createElement("div");
card.className="report-card";
card.innerHTML="<h3>Elemzés: Tokamak és Stellarátor Anyagtudományi Kihívásai</h3><p>Az anyagfáradás és erózió korlátokat szab a fúziós reaktorok teljesítményének. Az elemzés kiemeli a wolfram és kompozit anyagok előnyeit és kockázatait.</p><button id='open-report'>Teljes Jelentés Megnyitása</button>";
liveWidget.innerHTML="";
liveWidget.appendChild(card);
const openBtn=document.getElementById("open-report");
openBtn.addEventListener("click",()=>{
reportModal.style.display="block";
reportContent.innerHTML="<h2>Teljes Jelentés: Tokamak és Stellarátor Anyagtudományi Kihívásai</h2><p>Ez a részletes dokumentum elemzi a nagy hőmérsékletű plazma által okozott anyagkárosodásokat, a mágneses tér korlátait és az anyagszerkezet fejlődését. Tartalmaz táblázatokat, idézeteket és forrásjegyzéket.</p><p><b>Források:</b></p><ul><li>Nature Fusion 2024</li><li>ScienceDirect 2025</li></ul>";
});
},1500);
}
},1200);
});
closeReport.addEventListener("click",()=>{reportModal.style.display="none";});
</script>
</body>
</html>
